mapper.select:


    del_flag = '0'

        and record_type = #{recordType}


        and record_name like concat('%', #{recordName}, '%')


        and category_code = #{categoryCode}


        and stat_month = #{statMonth}


        and portal_code = #{portalCode}


        and workflow_status = #{workflowStatus}


        and status = #{status}


        and region_code like concat(#{regionCode}, '%')


        and enterprise_id = #{enterpriseId}


        and enterprise_name like concat('%', #{enterpriseName}, '%')


        and person_id = #{personId}


        and person_name like concat('%', #{personName}, '%')


        and payload_json like concat('%\"platformName\":\"', #{platformName}, '\"%')


        and payload_json like concat('%\"industryType\":\"', #{industryType}, '\"%')


        and payload_json like concat('%\"warningLevel\":\"', #{warningLevel}, '\"%')

    ${params.regionDataScope}

order by sort_order asc, record_id desc
